// verify-native-surface.mjs
//
// OFFLINE ONLY — never imported by app code. Asserts that the NATIVE surface
// generated by `expo prebuild --clean` is what the shipped TribeLife build has:
// the iOS Notification Service Extension and Communication Notifications wiring,
// URL schemes / associated domains, Firebase kept out of the iOS binary, the
// Android FCM / channel / market-query / app-link / ConversationShortcut wiring,
// and NO background audio (iOS UIBackgroundModes audio, Android media-playback
// foreground service) — expo-audio >= 55 turns background playback ON by default
// unless the plugin option `enableBackgroundPlayback: false` is set in app.json.
// No network, no database, no Expo/Xcode/Gradle invocation: it only reads files.
//
// Expected values (URL schemes, associated domains, bundle id, app-link hosts and
// path prefixes, android permissions, android package) are read from
// <root>/app.json at run time, never duplicated here.
//
// Modes
//   --platform ios|android     check one generated native project under <root>/ios or <root>/android
//   --compare-manifests <shipped.xml> <new.xml>
//                              diff two merged Android manifests; fails only on an ADDED
//                              FOREGROUND_SERVICE* permission, an ADDED service that declares
//                              foregroundServiceType, or more MESSAGING_EVENT actions than shipped
//
// Options
//   --root <dir>               project root (default: this script's parent, tribelife-mobile/)
//   --ios-min <version>        expected iOS deployment target (default 15.1; Phase 41 passes 16.4)
//   --allow-missing-lock       skip the Podfile.lock checks (after a `prebuild --no-install`)
//
// Usage (from tribelife-mobile/), after the matching prebuild:
//   npx expo prebuild -p ios --clean
//   node --no-warnings scripts/verify-native-surface.mjs --platform ios
//   RNFB_ANDROID=1 npx expo prebuild -p android --clean
//   node --no-warnings scripts/verify-native-surface.mjs --platform android
//   node --no-warnings scripts/verify-native-surface.mjs --compare-manifests <shipped.xml> <new.xml>
//   Requires Node v22.18+ (same .mjs rationale as scripts/verify-link-clicks.mjs).
//
// Prints NATIVE_SURFACE_OK (exit 0) or NATIVE_SURFACE_FAIL <check ids> (exit 1);
// compare mode prints ADDED/REMOVED lines, then MANIFEST_DIFF_OK (exit 0) or
// MANIFEST_DIFF_FAIL <offending names> (exit 1). Absent input is never OK
// (ios:missing-project / android:missing-project).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));

// ── Args ────────────────────────────────────────────────────────────────────
const argv = process.argv.slice(2);
const flag = (name) => argv.includes(name);
const value = (name, fallback) => {
  const i = argv.indexOf(name);
  return i >= 0 && argv[i + 1] !== undefined ? argv[i + 1] : fallback;
};

const read = (p) => {
  try { return fs.readFileSync(p, 'utf8'); } catch { return null; }
};
const stripComments = (xml) => xml.replace(/<!--[\s\S]*?-->/g, '');
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// ── XML helpers (regex-based; manifests put attributes across lines) ───────
function parseAttrs(s) {
  const attrs = {};
  for (const m of s.matchAll(/([\w:.-]+)\s*=\s*"([^"]*)"/g)) attrs[m[1]] = m[2];
  return attrs;
}
function elements(xml, tag) {
  const out = [];
  const open = new RegExp(`<${esc(tag)}(?=[\\s/>])([^>]*?)(/?)>`, 'g');
  for (const m of xml.matchAll(open)) {
    let body = '';
    if (m[2] !== '/') {
      const end = xml.indexOf(`</${tag}>`, m.index + m[0].length);
      if (end >= 0) body = xml.slice(m.index + m[0].length, end);
    }
    out.push({ attrs: parseAttrs(m[1]), body });
  }
  return out;
}

// ── Compare mode ────────────────────────────────────────────────────────────
function summarize(xml) {
  const x = stripComments(xml);
  const permissions = new Set();
  for (const e of elements(x, 'uses-permission')) {
    if (e.attrs['tools:node'] === 'remove') continue;
    if (e.attrs['android:name']) permissions.add(e.attrs['android:name']);
  }
  const services = new Map();
  for (const e of elements(x, 'service')) {
    if (e.attrs['tools:node'] === 'remove') continue;
    services.set(e.attrs['android:name'], e.attrs['android:foregroundServiceType'] || '');
  }
  const receivers = new Set();
  for (const e of elements(x, 'receiver')) {
    if (e.attrs['tools:node'] === 'remove') continue;
    receivers.add(e.attrs['android:name']);
  }
  const messagingEvents = (x.match(/com\.google\.firebase\.MESSAGING_EVENT/g) || []).length;
  return { permissions, services, receivers, messagingEvents };
}

if (flag('--compare-manifests')) {
  const i = argv.indexOf('--compare-manifests');
  const shippedPath = argv[i + 1];
  const newPath = argv[i + 2];
  const shippedXml = shippedPath ? read(path.resolve(shippedPath)) : null;
  const newXml = newPath ? read(path.resolve(newPath)) : null;
  if (shippedXml === null || newXml === null) {
    console.log('MANIFEST_DIFF_FAIL missing-input');
    process.exit(1);
  }
  const a = summarize(shippedXml);
  const b = summarize(newXml);
  const offenders = [];
  const report = (kind, what, name) => console.log(`${kind} ${what} ${name}`);

  for (const p of [...b.permissions].sort()) {
    if (a.permissions.has(p)) continue;
    report('ADDED', 'permission', p);
    if (p.includes('FOREGROUND_SERVICE')) offenders.push(p);
  }
  for (const p of [...a.permissions].sort()) if (!b.permissions.has(p)) report('REMOVED', 'permission', p);

  for (const [n, fgs] of [...b.services].sort()) {
    if (a.services.has(n)) continue;
    report('ADDED', 'service', fgs ? `${n} foregroundServiceType=${fgs}` : n);
    if (fgs) offenders.push(n);
  }
  for (const n of [...a.services.keys()].sort()) if (!b.services.has(n)) report('REMOVED', 'service', n);

  for (const n of [...b.receivers].sort()) if (!a.receivers.has(n)) report('ADDED', 'receiver', n);
  for (const n of [...a.receivers].sort()) if (!b.receivers.has(n)) report('REMOVED', 'receiver', n);

  if (b.messagingEvents > a.messagingEvents) {
    console.log(`ADDED MESSAGING_EVENT actions ${a.messagingEvents} -> ${b.messagingEvents}`);
    offenders.push(`MESSAGING_EVENT:${a.messagingEvents}->${b.messagingEvents}`);
  } else if (b.messagingEvents < a.messagingEvents) {
    console.log(`REMOVED MESSAGING_EVENT actions ${a.messagingEvents} -> ${b.messagingEvents}`);
  }

  if (offenders.length) {
    console.log('MANIFEST_DIFF_FAIL ' + offenders.join(' '));
    process.exit(1);
  }
  console.log('MANIFEST_DIFF_OK');
  process.exit(0);
}

// ── Platform mode ───────────────────────────────────────────────────────────
const platform = value('--platform');
if (platform !== 'ios' && platform !== 'android') {
  console.error('Usage: node --no-warnings scripts/verify-native-surface.mjs --platform ios|android [--root <dir>] [--ios-min <v>] [--allow-missing-lock]');
  console.error('       node --no-warnings scripts/verify-native-surface.mjs --compare-manifests <shipped.xml> <new.xml>');
  process.exit(2);
}
const root = path.resolve(value('--root', path.resolve(here, '..')));
const iosMin = value('--ios-min', '15.1');
const allowMissingLock = flag('--allow-missing-lock');

const fails = [];
const ok = (cond, id) => { if (!cond && !fails.includes(id)) fails.push(id); };
const finish = () => {
  if (fails.length) {
    console.log('NATIVE_SURFACE_FAIL ' + fails.join(' '));
    process.exit(1);
  }
  console.log('NATIVE_SURFACE_OK');
  process.exit(0);
};

// Expected values come from app.json (never duplicated here). Loaded AFTER the
// missing-project check so an absent ios/ or android/ always reports
// <platform>:missing-project, never a misleading app.json error.
let bundleId, androidPackage, schemes, associatedDomains, appLinkTargets, androidPermissions;
function loadExpected() {
  let expo;
  try {
    expo = JSON.parse(fs.readFileSync(path.join(root, 'app.json'), 'utf8')).expo;
  } catch {
    expo = null;
  }
  if (!expo) {
    console.log('NATIVE_SURFACE_FAIL app-json-unreadable');
    process.exit(1);
  }
  bundleId = expo.ios?.bundleIdentifier;
  androidPackage = expo.android?.package;
  schemes = [
    ...new Set([
      ...(expo.ios?.infoPlist?.CFBundleURLTypes || []).flatMap((t) => t.CFBundleURLSchemes || []),
      ...(expo.scheme ? [expo.scheme] : []),
    ]),
  ];
  associatedDomains = expo.ios?.associatedDomains || [];
  appLinkTargets = (expo.android?.intentFilters || [])
    .filter((f) => f.autoVerify)
    .flatMap((f) => (f.data || []).filter((d) => d.pathPrefix).map((d) => ({ host: d.host, pathPrefix: d.pathPrefix })));
  androidPermissions = expo.android?.permissions || [];
}

// ── iOS ─────────────────────────────────────────────────────────────────────
if (platform === 'ios') {
  const iosDir = path.join(root, 'ios');
  let appName = null;
  try {
    const proj = fs.readdirSync(iosDir).find((f) => f.endsWith('.xcodeproj') && f !== 'Pods.xcodeproj');
    if (proj) appName = proj.replace(/\.xcodeproj$/, '');
  } catch { /* ios/ absent */ }
  const pbxproj = appName ? read(path.join(iosDir, `${appName}.xcodeproj`, 'project.pbxproj')) : null;
  if (pbxproj === null) {
    ok(false, 'ios:missing-project');
    finish();
  }
  loadExpected();

  // NSE target, bundle id, deployment target.
  ok(/name = NotificationService;/.test(pbxproj) && pbxproj.includes('NotificationService.appex'), 'ios:nse-target');
  const nseBundle = new RegExp(`PRODUCT_BUNDLE_IDENTIFIER = "?${esc(String(bundleId))}\\.notificationservice"?;`);
  ok(Boolean(bundleId) && nseBundle.test(pbxproj), 'ios:nse-bundle-id');
  const chunks = pbxproj.split('isa = XCBuildConfiguration;').slice(1);
  const nseConfigs = chunks.filter((c) => nseBundle.test(c));
  const wantTarget = new RegExp(`IPHONEOS_DEPLOYMENT_TARGET = "?${esc(iosMin)}"?;`);
  ok(nseConfigs.length > 0 && nseConfigs.every((c) => wantTarget.test(c)), 'ios:nse-deployment-target');

  // Main entitlements.
  const entitlements = read(path.join(iosDir, appName, `${appName}.entitlements`)) || '';
  ok(/<key>com\.apple\.developer\.usernotifications\.communication<\/key>\s*<true\s*\/>/.test(entitlements), 'ios:comm-entitlement');
  ok(associatedDomains.length > 0 && associatedDomains.every((d) => entitlements.includes(`<string>${d}</string>`)), 'ios:associated-domains');

  // Main Info.plist.
  const plist = read(path.join(iosDir, appName, 'Info.plist')) || '';
  const activityTypes = /<key>NSUserActivityTypes<\/key>\s*<array>([\s\S]*?)<\/array>/.exec(plist);
  ok(Boolean(activityTypes) && activityTypes[1].includes('<string>INSendMessageIntent</string>'), 'ios:send-message-intent');
  const urlSchemeBlocks = [...plist.matchAll(/<key>CFBundleURLSchemes<\/key>\s*<array>([\s\S]*?)<\/array>/g)].map((m) => m[1]).join('\n');
  ok(schemes.length > 0 && schemes.every((s) => urlSchemeBlocks.includes(`<string>${s}</string>`)), 'ios:url-schemes');
  const bgModes = /<key>UIBackgroundModes<\/key>\s*<array>([\s\S]*?)<\/array>/.exec(plist);
  ok(!(bgModes && bgModes[1].includes('<string>audio</string>')), 'ios:no-bg-audio');

  // Podfile + properties.
  const podfile = read(path.join(iosDir, 'Podfile'));
  ok(podfile !== null && podfile.includes(`podfile_properties['ios.deploymentTarget'] || '${iosMin}'`), 'ios:podfile-platform');
  const propsRaw = read(path.join(iosDir, 'Podfile.properties.json'));
  let props = {};
  try { props = propsRaw ? JSON.parse(propsRaw) : {}; } catch { ok(false, 'ios:podfile-platform'); }
  if (props['ios.deploymentTarget'] !== undefined && String(props['ios.deploymentTarget']) !== iosMin) ok(false, 'ios:podfile-platform');
  ok(props.newArchEnabled !== 'false' && props.newArchEnabled !== false, 'ios:newarch');

  // Podfile.lock: no Firebase pods in the iOS binary; Fabric present.
  const lock = read(path.join(iosDir, 'Podfile.lock'));
  if (lock === null) {
    if (!allowMissingLock) ok(false, 'ios:podfile-lock-missing');
  } else {
    ok(!/^\s*- "?(Firebase|RNFB|RNNotifee)/m.test(lock), 'ios:no-firebase-pods');
    ok(lock.includes('React-Fabric'), 'ios:fabric');
  }
  finish();
}

// ── Android ─────────────────────────────────────────────────────────────────
const androidDir = path.join(root, 'android');
const manifestRaw = read(path.join(androidDir, 'app', 'src', 'main', 'AndroidManifest.xml'));
if (manifestRaw === null) {
  ok(false, 'android:missing-project');
  finish();
}
loadExpected();
const manifest = stripComments(manifestRaw);

const EXPO_FCM_SERVICE = 'expo.modules.notifications.service.ExpoFirebaseMessagingService';
const DEFAULT_CHANNEL_META = 'com.google.firebase.messaging.default_notification_channel_id';
const FGS_MEDIA_PLAYBACK = 'android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK';
const AUDIO_SERVICES = ['expo.modules.audio.service.AudioControlsService', 'expo.modules.audio.service.AudioRecordingService'];

const services = elements(manifest, 'service');
const metaData = elements(manifest, 'meta-data');
const usesPermissions = elements(manifest, 'uses-permission');

ok(services.some((s) => s.attrs['android:name'] === EXPO_FCM_SERVICE && s.attrs['tools:node'] === 'remove'), 'android:expo-fcm-removed');
ok(metaData.some((m) => m.attrs['android:name'] === DEFAULT_CHANNEL_META && m.attrs['tools:replace'] === 'android:value'), 'android:default-channel-replace');
ok(elements(manifest, 'queries').some((q) => /android:scheme="market"/.test(q.body)), 'android:market-query');

// App links: every autoVerify path prefix from app.json, for its host.
const verifiedFilters = elements(manifest, 'intent-filter').filter((f) => f.attrs['android:autoVerify'] === 'true');
const verifiedData = verifiedFilters.flatMap((f) => elements(f.body, 'data').map((d) => d.attrs));
ok(
  verifiedFilters.length > 0 &&
    appLinkTargets.length > 0 &&
    appLinkTargets.every((t) => verifiedData.some((d) => d['android:host'] === t.host && d['android:pathPrefix'] === t.pathPrefix)),
  'android:applinks',
);

const declaredPermissions = new Set(usesPermissions.filter((p) => p.attrs['tools:node'] !== 'remove').map((p) => p.attrs['android:name']));
ok(androidPermissions.every((p) => declaredPermissions.has(p)), 'android:permissions');

// ConversationShortcut registration + sources.
const javaDir = path.join(androidDir, 'app', 'src', 'main', 'java', ...String(androidPackage).split('.'));
const mainApplication = read(path.join(javaDir, 'MainApplication.kt')) || '';
ok(Boolean(androidPackage) && mainApplication.includes(`import ${androidPackage}.shortcuts.ConversationShortcutPackage`), 'android:shortcut-import');
ok(mainApplication.includes('ConversationShortcutPackage()'), 'android:shortcut-register');
ok(['ConversationShortcutModule.kt', 'ConversationShortcutPackage.kt'].every((f) => fs.existsSync(path.join(javaDir, 'shortcuts', f))), 'android:shortcut-sources');

// No background audio: no expo-audio services, no media-playback foreground service permission.
ok(!services.some((s) => AUDIO_SERVICES.includes(s.attrs['android:name']) && s.attrs['tools:node'] !== 'remove'), 'android:no-audio-services');
ok(usesPermissions.filter((p) => p.attrs['android:name'] === FGS_MEDIA_PLAYBACK).every((p) => p.attrs['tools:node'] === 'remove'), 'android:fgs-media-playback-removed');

// New Architecture: the SDK 55 template still writes newArchEnabled=true; only `false` is a failure.
const gradleProps = read(path.join(androidDir, 'gradle.properties')) || '';
ok(gradleProps !== '' && !/^\s*newArchEnabled\s*=\s*false\s*$/m.test(gradleProps), 'android:newarch');

finish();
